Bash(cd /c/Users/gohyi/road-detector && node --input-type=module -e "
// Replicate the osm.ts query for cell 2961
const south = 1.437258693875527;
const west = 103.78144474372444;
const north = 1.441780609313986;
const east = 103.78593782474167;

const latPad = \(north - south\) * 0.30;
const lngPad = \(east - west\) * 0.30;
const qSouth = south - latPad;
const qWest = west - lngPad;
const qNorth = north + latPad;
const qEast = east + lngPad;

const query = '[out:json][timeout:10];\(way[\\"highway\\"][\\"name\\"]\(' + qSouth + ',' + qWest + ',' + qNorth + ',' + qEast + '\);\);out geom;';

console.log\('Query bbox:', qSouth.toFixed\(6\), qWest.toFixed\(6\), qNorth.toFixed\(6\), qEast.toFixed\(6\)\);

const resp = await fetch\('https://overpass-api.de/api/interpreter', {
  method: 'POST', body: query,
  headers: { 'Content-Type': 'text/plain', 'User-Agent': 'RoadDetector/1.0' },
}\);
const data = await resp.json\(\);

const nww = data.elements?.filter\(e => e.tags?.name === 'North Woodlands Way'\);
for \(const el of \(nww || []\)\) {
  console.log\('North Woodlands Way:'\);
  console.log\('  highway:', el.tags?.highway\);
  console.log\('  geometry nodes:', el.geometry?.length || 0\);
  if \(el.geometry\) {
    for \(const n of el.geometry\) {
      console.log\('    ' + n.lat.toFixed\(6\) + ', ' + n.lon.toFixed\(6\)\);
    }
  }
}

if \(!nww?.length\) console.log\('North Woodlands Way NOT FOUND in this bbox'\);
" 2>&1)
